MODES = tuple(p["mode"] for p in PROFILE_OPERANDS)
M = module("fire_independent_model",HERE/"model.py")
model,plane_arrays,planes,RandomModel = M.model,M.plane_arrays,M.planes,M.RandomModel

def profiles():
    value = P.load(HERE / 'profiles.json')
    P.require(P.exact(value, PROFILE_OPERANDS),
              'fixed ordered Fire operands')
    return value


def sources():
    return {name: P.digest(HERE / name) for name in SOURCES}


def shared():
    return {name: P.digest(path) for name, path in SHARED.items()}


def class_pins():
    base = L.class_pins()
    extra = P.load(HERE / 'fire-method-pins.json')
    validate_class_pins(extra)
    return {'archive': base['archive'], 'classes': {**base['classes'], **extra['classes']}}


def validate_class_pins(extra):
    P.require(type(extra) is dict and set(extra) == {'archive_sha256', 'classes', 'methods'} and
              extra['archive_sha256'] == P.JAR and type(extra['classes']) is dict and
              set(extra['classes']) == set(CLASS_IDENTITIES), 'closed additional Fire/light classes')
    for name, (size, digest, parent, structure) in CLASS_IDENTITIES.items():
        class_record(extra['classes'][name], name, size, digest, parent)
        P.require(G.structural_hash(extra['classes'][name]) == structure, 'complete additional original class structure')
    expected = SELECTED_METHODS
    P.require(P.exact(extra['methods'], expected), 'closed additional original Code inventory')


def method_pins():
    classes, result = class_pins()['classes'], L.method_pins()
    expected = SELECTED_METHODS
    value = P.load(HERE / 'fire-method-pins.json')
    P.require(P.exact(value['methods'], expected), 'closed original Fire Code pins')
    for key, identity in expected.items():
        owner, rest = key.split('.', 1)
        name, descriptor = rest.split('(', 1)
        descriptor = '(' + descriptor
        found = [m for m in classes[owner]['methods'] if m['name'] == name and m['descriptor'] == descriptor]
        P.require(len(found)==1 and P.exact({k:found[0][k] for k in identity},identity),'unchanged original Fire Code')
        result[key] = identity
    return result


def validate(rows):
    P.require(type(rows) is list and len(rows)==71,'seventy-one ordered Fire rows')
    scheduled={'initialized':False,'sequence':'0'*16}
    entity={'initialized':False,'next_id':0}
    for row,profile in zip(rows,profiles()):
        P.require(type(row) is dict and set(row)=={'mode','prepared','prepared_class','receiver','before','after',
            'result','exception','exception_message','exception_stack','events'} and row['mode']==profile['mode'],
            'closed ordered Fire source row')
        P.require(P.exact(row['prepared'],profile),'complete fixed declared Fire operands')
        prepared={'scheduled':dict(scheduled),'entity':dict(entity)}
        P.require(P.exact(row['prepared_class'],prepared),'passive absolute Source class state before preparation')
        expected=model(profile,prepared)
        P.require(P.exact(row['receiver'],{'class':'nx' if profile['entry_id']==11 else 'yq','fire_class':'yq'}),
                  'actual unchanged concrete receiver')
        for phase in ('before','after'):
            state=dict(expected[phase],chunk_planes=planes(profile,phase=='after',expected))
            P.require(P.exact(row[phase],state),'independent complete '+phase+' Fire/World/Chunk/Random state')
        for key in ('result','exception','exception_message'):
            P.require(P.exact(row[key],expected[key]),'actual first return or genuine Throwable '+key)
        P.require(type(row['events']) is list and len(row['events'])==len(expected['events']),'exact actual callback count')
        for event,prediction in zip(row['events'],expected['events']):
            P.require(type(event) is dict and set(event)==(set(prediction)-{'source_stack'})|{'stack'} and
                      P.exact({k:v for k,v in event.items() if k!='stack'},
                              {k:v for k,v in prediction.items() if k!='source_stack'}),
                      'independent ordered effect parameters, captured cells, entropy and publication prefix')
            full_trace(event['stack'],prediction['source_stack'],prediction['kind'])
        if expected['exception']=='NONE':P.require(P.exact(row['exception_stack'],[]),'no invented Throwable')
        else:
            observer=expected['exception']=='java/lang/IllegalStateException'
            kind=expected['events'][-1]['kind'] if observer else None
            full_trace(row['exception_stack'],expected['exception_source_stack'],kind,exception=True)
        scheduled={k:expected['after']['scheduled'][k] for k in ('initialized','sequence')}
        entity=dict(expected['after']['entity_class'])


def full_trace(value,source,kind,exception=False):
    F.trace(value)
    callback='b' if kind=='range' else 'e' if kind=='sky' else 'a'
    prefix=[] if exception else ['java.lang.Thread.getStackTrace','FireObservation$Observer.event']
    if kind is not None:prefix.append('FireObservation$Observer.'+callback)
    expected=[*prefix,*source,'FireObservation.run','FireObservation.main']
    P.require(P.exact([frame['class']+'.'+frame['method'] for frame in value],expected),
              'complete unchanged Source/authored callback/Throwable frame order')
    for frame in value:
        file=('Thread.java' if frame['class']=='java.lang.Thread' else
              'FireObservation.java' if frame['class'].startswith('FireObservation') else 'SourceFile')
        P.require(frame['file']==file,'actual unchanged or authored frame file')


def validate_finite(value):
    P.require(type(value) is dict and set(value) == {'schema', 'scope', 'rows'} and
              value['schema'] == SCHEMA and value['scope'] == SCOPE, 'closed original-only Fire envelope')
    validate(value['rows'])


def validate_provenance(proof, directory=HERE):
    directory = Path(directory)
    keys = {'schema', 'status', 'archive_sha256', 'finite_sha256', 'capture_sha256', 'sources', 'shared',
            'methods', 'helpers', 'binaries', 'class_count', 'rows_per_vm', 'original', 'processes',
            'inputs_unchanged', 'helpers_unchanged', 'class_names_unchanged', 'class_pins_unchanged'}
    P.require(type(proof) is dict and set(proof) == keys and proof['schema'] == PROVENANCE and
              proof['status'] == 'PASS_ORIGINAL_CPU_COMPONENTS_ONLY' and proof['archive_sha256'] == P.JAR and
              proof['finite_sha256'] == P.digest(directory / 'finite.json') and P.word(proof['capture_sha256'], 64) and
              P.exact(proof['class_count'], 58) and P.exact(proof['rows_per_vm'], 71) and
              all(proof[k] is True for k in ('inputs_unchanged', 'helpers_unchanged', 'class_names_unchanged', 'class_pins_unchanged')),
              'closed original Fire provenance and complete input preservation')
    for key, names in (('sources', SOURCES), ('shared', SHARED), ('helpers', HELPERS), ('binaries', BINARIES)):
        F.fingerprints(proof[key], names, 'closed ' + key + ' inventory')
    P.require(P.exact(proof['sources'], sources()) and P.exact(proof['shared'], shared()) and
              P.exact(proof['methods'], method_pins()) and proof['binaries']['client'] == P.JAR and
              all(proof['binaries'][name] == digest for name, digest in P.LIBRARIES.items()), 'actual original Code and inputs')
    P.require(type(proof['processes']) is dict and set(proof['processes']) == set(PROCESS_TIMEOUTS), 'five bounded tool processes')
    for label, timeout in PROCESS_TIMEOUTS.items(): receipt(proof['processes'][label], label, timeout)
    P.require(type(proof['original']) is list and len(proof['original']) == 2, 'two fresh original VMs')
    for index, value in enumerate(proof['original']): receipt(value, f'original-{index}', 70, original=True)
    P.require(all(P.exact(proof['original'][0][key], proof['original'][1][key]) for key in
                  ('exit', 'stdout_bytes', 'stderr_bytes', 'stdout_sha256', 'stderr_sha256')), 'identical unfiltered complete original streams')


def read_reference(directory=HERE):
    directory = Path(directory)
    value = P.load(directory / 'finite.json')
    validate_finite(value)
    validate_provenance(P.load(directory / 'provenance.json'), directory)
    return value


def check(directory=HERE):
    value = read_reference(directory)
    print('Original Fire packet: 71 profiles and bindings pass; native projection remains separate')
    return value


if __name__ == '__main__':
    check()
